'use strict';
let v170OpenReference;
function v170Text(de,en){return typeof window==='object'&&window.doppel6Language?.get()==='en'?en:de;}
function v170StoryText(career,e){
 if(e.type==='coach-news')return typeof window==='object'&&window.doppel6Language?.get()==='en'?window.doppel6Language.translate(e.text):e.text;
 const club=v66Club(career,e.clubId).name,competition=career.world.competitions.find(c=>c.id===e.competitionId),cup=competition.name||v170Text('nationalen Pokal','national cup');
 const texts={
 'europe-entry':()=>v170Text(`${club} spielt erstmals in dieser Karriere international: ${cup}.`,`${club} enters international football for the first time in this career: ${cup}.`),
 semifinal:()=>v170Text(`${club} erreicht erstmals in dieser Karriere das Halbfinale im ${cup}.`,`${club} reaches the ${cup} semifinal for the first time in this career.`),
 final:()=>v170Text(`${club} erreicht erstmals in dieser Karriere das Finale im ${cup}.`,`${club} reaches the ${cup} final for the first time in this career.`),
 title:()=>v170Text(`${club} gewinnt erstmals in dieser Karriere den ${cup}.`,`${club} wins the ${cup} for the first time in this career.`),
 reunion:()=>e.reason==='former-club'?v170Text(`Wiedersehen mit deiner früheren Station ${v66Club(career,e.otherClubId).name}.`,`A reunion with your former club ${v66Club(career,e.otherClubId).name}.`):v170Text(`Erneutes Duell mit ${v66Club(career,e.otherClubId).name}: Ihr habt euch bereits in einem internationalen Halbfinale oder Finale getroffen.`,`Another meeting with ${v66Club(career,e.otherClubId).name}: you previously met in an international semifinal or final.`),
 'youth-final':()=>v170Text(`${e.playerName} aus dem eigenen Nachwuchs erzielt in Minute ${e.goal.minute} das entscheidende Tor zum Finalsieg von ${club}.`,`${e.playerName} from the club's youth team scores the decisive goal in minute ${e.goal.minute} of ${club}'s final win.`),
 'country-place':()=>v170Text(`${club} trägt ${e.points} Punkte bei ${e.participants} Teilnehmern zur Länderwertung bei. Das Land erhält für Saison ${e.nextSeason} einen dritten Horizon-Platz.`,`${club} contributes ${e.points} points across ${e.participants} entrants to the country ranking. The country gains a third Horizon place for season ${e.nextSeason}.`)
 };return texts[e.type]();
}
function v170OfficeHTML(career){
 if(!v170Active(career))return'';const events=v170OfficeEvents(career),read=career.world.storyLog.readIds,unread=events.filter(e=>!read.includes(e.id)).length,esc=v161Escape;
 return `<details id="v170-office" translate="no"><summary>${v170Text('Vereinsbüro','Club office')} · ${unread} ${v170Text('ungelesen','unread')}</summary><p>${v170Text('Meilensteine deiner aktuellen Station. Meldungen halten den Spielbetrieb nicht auf.','Milestones at your current club. Messages do not interrupt your career.')}</p>${events.length?`<button type="button" data-v170-read="all">${v170Text('Alle als gelesen markieren','Mark all as read')}</button><ol>${events.map(e=>`<li><article><small>${v170Text('Saison','Season')} ${e.season} · ${typeof v172Date==='function'?v172Date(e.day):v62ShortDate(e.day)}${read.includes(e.id)?'':' · '+v170Text('Ungelesen','Unread')}</small>${e.competitionId&&['title','semifinal','final','europe-entry'].includes(e.type)?v62AwardIcon(career.world.competitions.find(c=>c.id===e.competitionId).format||'EU','europe',true):''}<p>${esc(v170StoryText(career,e))}</p><button type="button" data-v170-club="${esc(e.clubId)}">${v170Text('Verein ansehen','View club')}</button>${e.otherClubId?`<button type="button" data-v170-club="${esc(e.otherClubId)}">${esc(v66Club(career,e.otherClubId).name)}</button>`:''}${e.pid&&v66Player(career,e.pid)?`<button type="button" data-v170-player="${esc(e.pid)}">${v170Text('Spieler ansehen','View player')}</button>`:''}${e.fixtureId?`<button type="button" data-v170-fixture="${esc(e.fixtureId)}">${v170Text('Partie ansehen','View match')}</button>`:''}${read.includes(e.id)?'':`<button type="button" data-v170-read="${esc(e.id)}">${v170Text('Als gelesen markieren','Mark as read')}</button>`}</article></li>`).join('')}</ol>`:`<p>${v170Text('Noch keine Meilensteine erfasst.','No milestones recorded yet.')}</p>`}</details>`;
}
if(typeof document==='object')document.addEventListener('DOMContentLoaded',()=>{
 const style=document.createElement('style');style.textContent='#v170-office button,#v170-detail button[data-v170-close]{font:inherit;min-height:44px;padding:10px 12px;margin:4px;border:1px solid #799096;border-radius:8px;background:#d5f08d;color:#17252c;cursor:pointer}#v170-office article{padding:10px 0;border-bottom:1px solid #647b83}#v170-office small{color:inherit}#v170-detail{max-width:calc(100vw - 32px);overflow-wrap:anywhere}';document.head.append(style);
 const history=v68ClubHistory;v68ClubHistory=function(career,club){return history(career,club)+(v170Active(career)?`<section translate="no"><h3>${v170Text('Internationale Meilensteine','International milestones')}</h3><ul>${v170History(career,{clubId:club.id}).map(e=>`<li>${v170Text('Saison','Season')} ${e.season} · ${v161Escape(v170StoryText(career,e))}${e.fixtureId?`<button type="button" data-v170-fixture="${v161Escape(e.fixtureId)}">${v170Text('Partie ansehen','View match')}</button>`:''}</li>`).join('')}</ul></section>`:'');};
 const dialog=document.createElement('dialog');dialog.className='v61-profile-dialog';dialog.id='v170-detail';document.body.append(dialog);let returnButton;
 function show(html,button){if(dialog.open)dialog.close();returnButton=button;dialog.innerHTML=`<button type="button" data-v170-close>${v170Text('Zurück','Back')}</button>${html}`;dialog.showModal();}
 dialog.addEventListener('close',()=>returnButton?.isConnected&&returnButton.focus());
 dialog.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-v170-close'))dialog.close();else if(b.dataset.v170Fixture){v170OpenReference('fixture',b.dataset.v170Fixture,returnButton);}else if(b.dataset.v68Player){dialog.close();v68OpenPlayerProfile(v61CurrentCareer,b.dataset.v68Player,returnButton);}else if(b.dataset.v68Club){show(v68ClubDetailHTML(v61CurrentCareer,b.dataset.v68Club),returnButton);}else if(b.dataset.v68Coach){show(v68CoachDetailHTML(v61CurrentCareer,b.dataset.v68Coach),returnButton);}});
 v170OpenReference=function(kind,id,button){const career=v61CurrentCareer;if(kind==='club')show(v68ClubDetailHTML(career,id),button);else if(kind==='coach')show(v68CoachDetailHTML(career,id),button);else if(kind==='player')v68OpenPlayerProfile(career,id,button);else{const f=career.world.competitions.flatMap(c=>c.fixtures).find(f=>f.id===id),cup=career.world.competitions.find(c=>c.id===f.competitionId),esc=v161Escape;show(`<h2>${esc(cup.name||cup.id)}</h2><p>${v170Text('Saison','Season')} ${cup.season} · ${typeof v172Date==='function'?v172Date(f.day):v62Date(f.day)} · ${typeof v172Round==='function'?v172Round(f.round):f.round}</p><h3>${esc(v66Club(career,f.homeId).name)} ${f.result.homeGoals}:${f.result.awayGoals} ${esc(v66Club(career,f.awayId).name)}</h3>${f.result.aggregate?`<p>${v170Text('Gesamt','Aggregate')}: ${f.result.aggregate.join(':')}</p>`:''}${f.result.penalties?`<p>${v170Text('Elfmeterschießen','Penalty shootout')}: ${f.result.penalties.join(':')}</p>`:''}${f.matchRecord?.manOfMatchPid?`<p>${v62AwardIcon(cup.format||cup.country,'man-of-the-match',true)} Man of the Match · ${esc(v66Player(career,f.matchRecord.manOfMatchPid)?.name||f.matchRecord.manOfMatchPid)}</p>`:''}<ul>${(f.matchRecord?.events||[]).filter(e=>e.type==='goal').map(e=>`<li>${e.minute}′ · ${esc(v66Player(career,e.scorerPid)?.name||e.scorerPid)}</li>`).join('')}</ul>`,button);}};
 v61WorldScreen.addEventListener('click',async event=>{
  const button=event.target.closest('[data-v170-read],[data-v170-club],[data-v170-player],[data-v170-fixture]'),career=v61CurrentCareer;if(!button||!v170Active(career))return;
  try{
   if(button.dataset.v170Read){const ids=button.dataset.v170Read==='all'?v170OfficeEvents(career).map(e=>e.id):[button.dataset.v170Read];ids.forEach(id=>v170Read(career,id));await v64UiSave();const office=v61WorldScreen.querySelector('#v170-office');if(typeof v172Ui==='object'&&v172Ui.tab==='office'&&office.closest('.v172-career'))v61RenderCareer(career);else office.outerHTML=v170OfficeHTML(career);const next=v61WorldScreen.querySelector('#v170-office');next.open=true;next.querySelector('summary').focus();}
   else v170OpenReference(button.dataset.v170Club?'club':button.dataset.v170Player?'player':'fixture',button.dataset.v170Club||button.dataset.v170Player||button.dataset.v170Fixture,button);
  }catch(error){const status=v61WorldScreen.querySelector('#v166-message');if(status)status.textContent=error.message;}
 });
 const language=document.querySelector('#language-select');language?.addEventListener('change',()=>{const office=v61WorldScreen.querySelector('#v170-office');if(office&&v170Active(v61CurrentCareer)){const open=office.open;office.outerHTML=v170OfficeHTML(v61CurrentCareer);v61WorldScreen.querySelector('#v170-office').open=open;}});
});
